; Veranda resident core: calls into kernel banks
;
; Every banked routine NAME has a resident stub S_NAME (generated by
; tools/kbuild.py into build/kgen/stubs.s; API calls jump there from the
; jump table):
;
;	S_NAME:	sta gA
;		lda #3 * index          ; its entry in its bank's table at $A000
;		jmp TailN               ; the bank's own, shared by its stubs:
;	TailN:	sta gT
;		lda #bank               ; logical bank (BANK_x)
;		jmp FarGo
;
; FarGo maps the bank and jumps to the entry with the caller's a, x, y; the
; entry returns to FarRet, which maps the caller's RAM bank again and
; returns its a, x, y and flags. Cost: about 123 cycles there and back.
;
; Not reentrant by itself: gA, gT, gB, gP and gJump are the gate's state
; between its instructions. The interrupt handler saves and restores them
; (x16 IRQ entry, kernel/res/irq.s), so interrupt code may use FARCALL.

.include "kernel.inc"

.export FarGo, FarRet, kBankBase, kStride, kFx, kMemBanks, kMemTopX, kMemTopY
.export gA, gT, gB, gP, gJump, GATE_STATE, GATE_STATE_SIZE

.segment "DATA"

kBankBase:	.byte 0         ; RAM bank of BANK_G (set by the loader)
kStride:	.byte 80        ; bytes per screen row (40 in the 320 mode)
kMemBanks:	.byte 0         ; MEMTOP as the loader found it (restored on exit)
kMemTopX:	.byte 0
kMemTopY:	.byte 0
kFx:		.byte 0         ; bit 7: VERA FX cache writes for fills (Init)

GATE_STATE:                     ; the interrupt handler saves these 7 bytes
gA:		.byte 0
gT:		.byte 0
gB:		.byte 0
gP:		.byte 0
gJump:		jmp $A000       ; (the target of FarGo's last jump)
GATE_STATE_SIZE = * - GATE_STATE

.segment "CODE"

FarGo:
	clc
	adc kBankBase
	sta gB
	lda ram_bank            ; the caller's RAM bank, under the return
	pha
	lda #>(FarRet - 1)
	pha
	lda #<(FarRet - 1)
	pha
	lda gB
	sta ram_bank
	lda gT
	sta gJump+1
	lda gA
	jmp gJump               ; the entry: jmp to the routine

FarRet:
	sta gA
	php
	pla
	sta gP
	pla
	sta ram_bank            ; the caller's
	lda gP
	pha
	lda gA
	plp
	rts
